CREATE TABLE enterprise_identity_connections(workspace_id uuid NOT NULL,id uuid NOT NULL,name text NOT NULL,protocol text NOT NULL CHECK(protocol IN('saml','oidc')),issuer text NOT NULL,metadata jsonb NOT NULL,encrypted_configuration text NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','tested','active','disabled')),certificate_version integer NOT NULL DEFAULT 1,revision integer NOT NULL DEFAULT 1,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
CREATE TABLE verified_domains(workspace_id uuid NOT NULL,id uuid NOT NULL,domain text NOT NULL,challenge_hash text NOT NULL,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','verified','expired','conflict')),enforcement text NOT NULL DEFAULT 'none' CHECK(enforcement IN('none','discover','required')),verified_at timestamptz,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(workspace_id,id),UNIQUE(domain));
CREATE TABLE scim_credentials(workspace_id uuid NOT NULL,id uuid NOT NULL,prefix text NOT NULL,secret_hash text NOT NULL,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','revoked')),expires_at timestamptz NOT NULL,last_used_at timestamptz,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(prefix));
CREATE TABLE enterprise_policies(workspace_id uuid NOT NULL,id uuid NOT NULL,policy_key text NOT NULL,version integer NOT NULL DEFAULT 1,mode text NOT NULL CHECK(mode IN('dry_run','staged','enforced')),rules jsonb NOT NULL,exceptions jsonb NOT NULL DEFAULT '[]'::jsonb,revision integer NOT NULL DEFAULT 1,updated_by uuid NOT NULL,PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,policy_key));
CREATE TABLE scim_resources(workspace_id uuid NOT NULL,id uuid NOT NULL,external_id text,resource_type text NOT NULL CHECK(resource_type IN('User','Group')),document jsonb NOT NULL,active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id),UNIQUE(workspace_id,resource_type,external_id));
CREATE TABLE region_migrations(workspace_id uuid NOT NULL,id uuid NOT NULL,source_region text NOT NULL,target_region text NOT NULL CHECK(target_region IN('us','eu')),state text NOT NULL DEFAULT 'eligibility' CHECK(state IN('eligibility','blocked','freeze','copy','validate','cutover','rollback','purge','complete')),checks jsonb NOT NULL DEFAULT '[]'::jsonb,proof jsonb,requested_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(workspace_id,id));
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['enterprise_identity_connections','verified_domains','scim_credentials','enterprise_policies','scim_resources','region_migrations'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I_tenant ON %I USING (knotline_tenant_visible(workspace_id)) WITH CHECK (knotline_tenant_visible(workspace_id))',table_name,table_name);END LOOP;END $$;
REVOKE ALL ON enterprise_identity_connections,verified_domains,scim_credentials,enterprise_policies,scim_resources,region_migrations FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE,DELETE ON enterprise_identity_connections,verified_domains,scim_credentials,enterprise_policies,scim_resources,region_migrations TO knotline_runtime;
GRANT SELECT ON enterprise_identity_connections,verified_domains,enterprise_policies,scim_resources,region_migrations TO knotline_reporting;
